import{_ as a,c as s,o as e,b0 as i}from"./chunks/framework.C5ev1SXp.js";const u=JSON.parse('{"title":"LV025-NOINIT段简介","description":null,"frontmatter":{"title":"LV025-NOINIT段简介","date":"2026-10-15T15:53:45.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/basic/fault-and-hang/126d629c7291162664c24a27","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-15T15:53:45.354Z","fulluuid":"664c24a279b04a10b5ead1b68143128b","useduuid":"664c24a27"}},"headers":[],"relativePath":"sdoc/basic/fault-and-hang/126d629c7291162664c24a27.md","filePath":"sdoc/10-基础篇/80-异常与死机排查/LV025-NOINIT段简介.md","lastUpdated":1792231946000}'),n={name:"sdoc/basic/fault-and-hang/126d629c7291162664c24a27.md"};function d(o,t,r,l,c,h){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="lv025-noinit段简介" tabindex="-1">LV025-NOINIT段简介 <a class="header-anchor" href="#lv025-noinit段简介" aria-label="Permalink to &quot;LV025-NOINIT段简介&quot;">​</a></h1><p>看门狗复位能自动救活死机的单片机，但复位本身会把现场一起抹掉——崩溃时的运行状态、死因、复位来源全部丢失，重启之后只剩一脸茫然。解决办法是把现场存进 <strong>NOINIT 段</strong>：一块启动代码不碰的 RAM，让数据穿越复位保留下来。</p><p><a href="/scm-docs/sdoc/basic/fault-and-hang/126d629b776b05818a2b701b.html">LV001</a> 第 3.2 节已给出 NOINIT 的原理与 GNU ld 形态（<code>.noinit (NOLOAD)</code>），<a href="/scm-docs/sdoc/basic/fault-and-hang/126d629b7769c7e3f1a2c4d5.html">LV005</a> 讲了调试期的串口打印形态。本文补上第三种工程现实：<strong>Keil AC5 自动分散加载下怎么实现 NOINIT</strong>，以及看门狗场景下&quot;保存—复位—读取—消费&quot;的完整闭环。示例来自一个 bootloader + APP 双固件工程（F103ZE，64KB SRAM）。</p><h2 id="一、原理-复位不清-sram-抹掉现场的是启动代码" tabindex="-1">一、原理：复位不清 SRAM，抹掉现场的是启动代码 <a class="header-anchor" href="#一、原理-复位不清-sram-抹掉现场的是启动代码" aria-label="Permalink to &quot;一、原理：复位不清 SRAM，抹掉现场的是启动代码&quot;">​</a></h2><h3 id="_1-硬件侧-热复位不擦-sram" tabindex="-1">1. 硬件侧：热复位不擦 SRAM <a class="header-anchor" href="#_1-硬件侧-热复位不擦-sram" aria-label="Permalink to &quot;1. 硬件侧：热复位不擦 SRAM&quot;">​</a></h3><p>STM32F1 的 SRAM 是易失存储器，<strong>只有掉电才丢内容</strong>。而热复位源——NRST 引脚、软件 <code>SystemReset</code>、IWDG、WWDG、低功耗管理复位——按 (<a href="https://www.st.com/resource/en/reference_manual/rm0008-stm32f101xx-stm32f102xx-stm32f103xx-stm32f105xx-and-stm32f107xx-advanced-armbased-32bit-mcus-stmicroelectronics.pdf" target="_blank" rel="noreferrer">STM32F101xx, STM32F102xx, STM32F103xx, STM32F105xx and STM32F107xx advanced Arm®-based 32-bit MCUs - Reference manual</a>)（RM0008）的描述，复位的是内核状态与外设寄存器，<strong>SRAM 里的数据原样保留</strong>。</p><p>这是 NOINIT 可行的硬件基础：看门狗把芯片咬复位之后，死前写进 RAM 的数据还在原地。</p><h4 id="_1-1-手册出处-rcc-章的-reset-小节" tabindex="-1">1.1 手册出处：RCC 章的 Reset 小节 <a class="header-anchor" href="#_1-1-手册出处-rcc-章的-reset-小节" aria-label="Permalink to &quot;1.1 手册出处：RCC 章的 Reset 小节&quot;">​</a></h4><p>上述行为在 RM0008 中<strong>没有集中</strong>的&quot;一句话&quot;说明，出处是<strong>第 7 章 &quot;Low-, medium-, high- and XL-density reset and clock control (RCC)&quot; 的 §7.1 Reset</strong>（适用 F101/102/103；互联型 F105/107 对应第 8 章 §8.1；更老的 Rev 5～11 版本手册中 RCC 是第 6 章——章节号随版本漂移，按 &quot;Reset and Clock Control (RCC)&quot; 标题检索即可）。§7.1 把复位分成三类：</p><table tabindex="0"><thead><tr><th>复位类型</th><th>触发源（§7.1 原文归类）</th><th>SRAM 内容</th></tr></thead><tbody><tr><td>System reset（系统复位）</td><td>NRST 引脚低电平、WWDG、IWDG、软件复位、低功耗管理复位（§7.1.1）</td><td><strong>原样保留</strong></td></tr><tr><td>Power reset（电源复位）</td><td>POR/PDR、退出 Standby 模式（§7.1.2）</td><td><strong>丢失（随机值）</strong></td></tr><tr><td>Backup domain reset（备份域复位）</td><td>软件置位 BDRST、VDD 与 VBAT 均曾断电后重新上电（§7.1.3）</td><td>不受影响（只复位备份域）</td></tr></tbody></table><p>§7.1.1 对系统复位作用域的完整描述只有一句：</p><blockquote><p>A system reset sets all registers to their reset values except the reset flags in the clock controller CSR register and the registers in the Backup domain.</p></blockquote><p><strong>注意</strong>：手册从头到尾<strong>没有直接写&quot;复位后 SRAM 保留&quot;</strong>，这一结论是三处内容拼出的推论：</p><ul><li><p>§7.1.1 与 §7.1.2 的复位作用域只提 &quot;registers&quot;（寄存器），SRAM 不在其中；</p></li><li><p>第 3 章 Memory and bus architecture 的 Embedded SRAM 小节表明 SRAM 是独立的存储阵列，根本不属于寄存器域；</p></li><li><p>反证：第 5 章 PWR 的 §5.3.5 Standby mode 明确写了 1.8 V 域断电时 &quot;SRAM and register contents are lost except for registers in the Backup domain and Standby circuitry&quot;——只有 1.8 V 域断电的场景，手册才声明 SRAM 丢失。</p></li></ul><h4 id="_1-2-por-pdr-不能列入-保留-sram-的复位源" tabindex="-1">1.2 POR/PDR 不能列入&quot;保留 SRAM&quot;的复位源 <a class="header-anchor" href="#_1-2-por-pdr-不能列入-保留-sram-的复位源" aria-label="Permalink to &quot;1.2 POR/PDR 不能列入&quot;保留 SRAM&quot;的复位源&quot;">​</a></h4><p>POR/PDR 不属于热复位：按 §7.1.2 的归类，它与&quot;退出 Standby&quot;同属 <strong>Power reset（电源复位）</strong>。POR/PDR 触发即意味着 VDD 跌破阈值，SRAM 供电一度消失，重新上电后内容随机；退出 Standby 时 1.8 V 域已断电，SRAM 同样必丢。真正 SRAM 原样保留的只有 §7.1.1 列出的五类 <strong>System reset</strong>，共同点是复位前后供电从未断过——这与 3 小节&quot;冷启动后内容是随机值&quot;的边界自洽。</p><h3 id="_2-软件侧-main-才是凶手" tabindex="-1">2. 软件侧：<code>__main</code> 才是凶手 <a class="header-anchor" href="#_2-软件侧-main-才是凶手" aria-label="Permalink to &quot;2. 软件侧：\`__main\` 才是凶手&quot;">​</a></h3><p>复位后 CPU 从向量表偏移 0 处取初值装入 SP、从偏移 4 处取 <code>Reset_Handler</code> 地址装入 PC，<code>Reset_Handler</code> 随即调用 C 库的 <code>__main</code>（scatter-load 运行时）重建运行环境，动作只有两件：</p><table tabindex="0"><thead><tr><th>段</th><th>内容</th><th><code>__main</code> 的动作</th></tr></thead><tbody><tr><td><code>.data</code></td><td>有初值的全局/静态变量</td><td>从 Flash 的初始化表<strong>重新拷贝</strong>进 RAM</td></tr><tr><td><code>.bss</code></td><td>零初始化的全局/静态变量</td><td><strong>全部清零</strong></td></tr></tbody></table><p>于是出现一个反直觉的现象：<strong>硬件保留了现场，软件却把它还原了</strong>。死前改过的普通全局变量，重启那一刻被拷贝回初值或清零，等于自动毁尸灭迹。</p><h3 id="_3-noinit-的本质" tabindex="-1">3. NOINIT 的本质 <a class="header-anchor" href="#_3-noinit-的本质" aria-label="Permalink to &quot;3. NOINIT 的本质&quot;">​</a></h3><p>NOINIT 段就是<strong>一段既不进 <code>.data</code> 也不进 <code>.bss</code> 的 RAM</strong>：链接器的分散加载表里没有它，<code>__main</code> 的初始化动作自然落不到它头上，内容原样穿越复位。</p><p>它继承两条边界（与 LV001 的结论一致）：</p><ul><li><p><strong>冷启动后内容是随机值</strong>——刚上电时 SRAM 从未被本程序写过，读出来是什么全凭运气，所以必须用魔数判断&quot;这份内容是不是我们写的&quot;；</p></li><li><p><strong>掉电即丢</strong>——NOINIT 保留的是&quot;复位前&quot;的现场，不是&quot;上次运行&quot;的现场，不能替代 Flash 落盘。</p></li></ul><h2 id="二、实现方式与工程落地" tabindex="-1">二、实现方式与工程落地 <a class="header-anchor" href="#二、实现方式与工程落地" aria-label="Permalink to &quot;二、实现方式与工程落地&quot;">​</a></h2><h3 id="_1-三种实现方式对比" tabindex="-1">1. 三种实现方式对比 <a class="header-anchor" href="#_1-三种实现方式对比" aria-label="Permalink to &quot;1. 三种实现方式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>载体</th><th>工具链</th><th>需要自定义分散加载文件</th></tr></thead><tbody><tr><td><code>.ARM.__at_地址</code> 固定地址 section</td><td>armlink section 命名约定</td><td>Keil AC5 / AC6</td><td>否</td></tr><tr><td>自定义 <code>.sct</code> + <code>UNINIT</code> 执行区</td><td>Scatter File</td><td>Keil AC5 / AC6</td><td>是</td></tr><tr><td><code>.noinit (NOLOAD)</code> + ld 脚本</td><td>GNU ld</td><td>GCC</td><td>是</td></tr></tbody></table><p>LV001 用的是第三种。本文选第一种，理由：</p><p>（1）项目两个工程都用 <strong>Keil 自动分散加载</strong>（uvprojx 的 <code>&lt;ScatterFile /&gt;</code> 为空），引入自定义 <code>.sct</code> 意味着每次 CubeMX 重新生成、Keil 升级都要手动同步，纯维护负担；</p><p>（2）<code>.ARM.__at_地址</code> 是 armlink 的 section 命名约定，AC5 / AC6 通吃；</p><p>（3）地址钉死，行为完全可控，不依赖任何自动分配的运气。</p><p>代价是必须保证该地址不在 RAM 分配范围内（见 2.2 小节），以及它是 ARM 编译器专有语法——换 GCC 就要回到 ld <code>NOLOAD</code>。</p><h3 id="_2-keil-ac5-实战-固定地址-section" tabindex="-1">2. Keil AC5 实战：固定地址 section <a class="header-anchor" href="#_2-keil-ac5-实战-固定地址-section" aria-label="Permalink to &quot;2. Keil AC5 实战：固定地址 section&quot;">​</a></h3><h4 id="_2-1-变量声明" tabindex="-1">2.1 变量声明 <a class="header-anchor" href="#_2-1-变量声明" aria-label="Permalink to &quot;2.1 变量声明&quot;">​</a></h4><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// fault_scene.c</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 现场结构体定义见本文 3.1 小节 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__attribute__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.ARM.__at_0x2000FC00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">noinit_scene_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> g_scene;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>armlink 对名字形如 <code>.ARM.__at_&lt;地址&gt;</code> 的 section 有特殊处理：<strong>直接钉到指定绝对地址</strong>，不参与任何执行区的 <code>.ANY (+RO)</code> / <code>.ANY (+RW +ZI)</code> 匹配。分散加载表里查无此段，<code>__main</code> 自然不清零、不拷贝。</p><h4 id="_2-2-必须同步的一件事-ram-划分让位" tabindex="-1">2.2 必须同步的一件事：RAM 划分让位 <a class="header-anchor" href="#_2-2-必须同步的一件事-ram-划分让位" aria-label="Permalink to &quot;2.2 必须同步的一件事：RAM 划分让位&quot;">​</a></h4><p>F103ZE 有 64KB SRAM，uvprojx 里声明 <code>IRAM 0x20000000 / Size 0x10000</code>（全量）。Keil 自动生成的分散加载按这个 Size 划 RW/ZI 区，<strong>变量分配可以蔓延到 SRAM 最后一个字节</strong>。此时把 NOINIT 钉在 <code>0x2000FC00</code>，就存在被 ZI 分配撞上的风险——链接器对这种重叠不一定报错，可能静默共用一段 RAM。</p><p>所以要把两个工程（bootloader 与 APP）的 RAM 声明各让出 1KB：</p><div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- atk-f103.uvprojx / flash-app.uvprojx 的 OnChipMemories 段 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">IRAM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">StartAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;0x20000000&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">StartAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;0xFC00&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 原 0x10000, 让出尾部 1KB 给 NOINIT --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">IRAM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>效果：两边的 RW/ZI 都只分配到 <code>0x2000FBFF</code>，<code>0x2000FC00</code> 起的 1KB 双方都不初始化、专用于跨复位现场。现场结构体只有 24 字节，占用头部，剩余空间留作后续字段扩充。</p><h4 id="_2-3-与自定义-sct-的取舍" tabindex="-1">2.3 与自定义 <code>.sct</code> 的取舍 <a class="header-anchor" href="#_2-3-与自定义-sct-的取舍" aria-label="Permalink to &quot;2.3 与自定义 \`.sct\` 的取舍&quot;">​</a></h4><p>自定义 sct 配 <code>UNINIT</code> 执行区在语义上更规范（多个变量可顺序排布、无需手算地址），适合变量多、段属性复杂的场景；单块小场景用 <code>.ARM.__at_</code> 更轻——不动工程文件，不改变 CubeMX / Keil 的生成链路。本文场景（一块 24 字节的现场记录）属于后者。</p><h3 id="_3-双工程防互踩" tabindex="-1">3. 双工程防互踩 <a class="header-anchor" href="#_3-双工程防互踩" aria-label="Permalink to &quot;3. 双工程防互踩&quot;">​</a></h3><p>bootloader 与 APP 各自独立链接、都覆盖全量 RAM。如果只改一边，另一边的 ZI 分配可能伸进 NOINIT 区，把现场抹掉——有 <code>check</code> 兜底不会误报，但现场丢失，保留机制形同虚设。</p><p>地址布局约定：</p><table tabindex="0"><thead><tr><th>地址范围</th><th>用途</th></tr></thead><tbody><tr><td><code>0x20000000</code> ~ <code>0x2000FBFF</code></td><td>双方链接的 RW/ZI（各 63KB，实际用量远小于此）</td></tr><tr><td><code>0x2000FC00</code> ~ <code>0x2000FFFF</code></td><td>NOINIT 段（双方都不初始化，跨复位保留）</td></tr></tbody></table><p>两个 uvprojx 的 <code>&lt;IRAM&gt;&lt;Size&gt;</code> 同步从 <code>0x10000</code> 改为 <code>0xFC00</code>，RAM 布局就一致了。这一步是纯 XML 数值改动，不影响任何代码，但是整套机制可靠性的前提。</p><h2 id="三、现场数据结构与看门狗闭环" tabindex="-1">三、现场数据结构与看门狗闭环 <a class="header-anchor" href="#三、现场数据结构与看门狗闭环" aria-label="Permalink to &quot;三、现场数据结构与看门狗闭环&quot;">​</a></h2><h3 id="_1-现场数据-先盘全景-再挑关键字段" tabindex="-1">1. 现场数据：先盘全景，再挑关键字段 <a class="header-anchor" href="#_1-现场数据-先盘全景-再挑关键字段" aria-label="Permalink to &quot;1. 现场数据：先盘全景，再挑关键字段&quot;">​</a></h3><h4 id="_1-1-全景-有哪些数据可以写" tabindex="-1">1.1 全景：有哪些数据可以写 <a class="header-anchor" href="#_1-1-全景-有哪些数据可以写" aria-label="Permalink to &quot;1.1 全景：有哪些数据可以写&quot;">​</a></h4><p>NOINIT 段本质是一块&quot;重启后还能读到的内存&quot;，里面可以放任何想留给下一次启动的数据。设计结构体的第一步，是知道有哪些可选：</p><table tabindex="0"><thead><tr><th>类别</th><th>典型数据</th><th>回答的问题</th></tr></thead><tbody><tr><td>死因与复位源</td><td><code>cause</code> 死因枚举、<code>RCC-&gt;CSR</code> 复位源快照、复位累计计数</td><td>怎么死的、谁复位的</td></tr><tr><td>异常栈帧</td><td>R0~R3 / R12 / LR / PC / xPSR、<code>SCB-&gt;CFSR</code> / <code>HFSR</code>、<code>MMFAR</code> / <code>BFAR</code>、栈顶快照</td><td>崩溃发生在哪条指令、访问了什么非法地址（仅崩溃时可取到）</td></tr><tr><td>运行状态</td><td>心跳 <code>uptime_ms</code>、状态机阶段号、位置埋点编号、当前任务句柄（RTOS）</td><td>死前跑到哪一步、卡在哪个任务</td></tr><tr><td>通信与外设</td><td>错误码、CRC / 重传计数、总线错误计数（如 CAN / I2C 卡死状态）</td><td>是不是通信异常诱发的</td></tr><tr><td>环境与版本</td><td>固件版本号或 commit hash、RTC 时间戳、电池电压、设备序列号</td><td>哪个版本、哪台设备、什么时候死的</td></tr><tr><td>完整性管理</td><td><code>magic</code> 魔数、<code>check</code> 校验和、结构体版本号</td><td>这份记录本身可不可信</td></tr></tbody></table><p>前四类描述&quot;案发现场&quot;，后两类保证&quot;现场可信&quot;。</p><p>这些数据不需要全写，挑选标准只有一条：<strong>读回来之后，能不能帮你定位或修复问题</strong>。按这条标准，三类必留：</p><ul><li><p><strong>能定死因的</strong>（<code>cause</code>、<code>rcc_csr</code>）：不知道怎么死的，后面一切都是瞎猜；</p></li><li><p><strong>能定位置的</strong>（<code>uptime_ms</code>、<code>pc_hint</code>）：不知道死在哪，知道了死因也修不了；</p></li><li><p><strong>能判可信的</strong>（<code>magic</code>、<code>check</code>）：冷启动后 SRAM 是随机值，没有它们会把垃圾数据当现场。</p></li></ul><p>其余字段按工程实际增删：RTOS 工程补当前任务句柄与任务名；多版本并存的量产固件补版本号，防止升级后字段含义对不上；怀疑通信诱发的补错误计数。容量上也不允许全塞——本文 NOINIT 区只有 1KB，现场数据是给&quot;下一次启动分析&quot;用的，要全量回放该走 LV001 的 Flash 落盘。</p><h4 id="_1-2-本文的选择-最小必要-6-字段" tabindex="-1">1.2 本文的选择：最小必要 6 字段 <a class="header-anchor" href="#_1-2-本文的选择-最小必要-6-字段" aria-label="Permalink to &quot;1.2 本文的选择：最小必要 6 字段&quot;">​</a></h4><p>三类必留、每类取两个字段，就是本文的结构体：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// fault_scene.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> magic;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 魔数: 内容是否有效 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cause;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 死因: 看门狗超时 / deadloop / HardFault */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uptime_ms;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* 死前心跳(HAL_GetTick) */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rcc_csr;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* RCC-&gt;CSR 快照: 区分复位源 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pc_hint;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 死前 PC(HardFault 时有值) */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> check;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 校验和: 前 5 项之和, 防半写 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">noinit_scene_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>六个字段各管一件事：<code>magic</code> 判断内容是不是自己写的，<code>cause</code> 记死因，<code>uptime_ms</code> 记死前活到哪一刻，<code>rcc_csr</code> 记这次重启是谁复位的，<code>pc_hint</code> 记死前 PC，<code>check</code> 防半写。</p><p>其中 <code>magic</code> / <code>check</code> / <code>uptime_ms</code> 是机制性字段——它们不描述死机本身，缺了任何一个，读到的现场都不可信：</p><table tabindex="0"><thead><tr><th>机制</th><th>防什么问题</th></tr></thead><tbody><tr><td><code>magic</code> 魔数</td><td>冷启动 SRAM 是随机值，没有魔数会把随机数据当现场误报</td></tr><tr><td><code>check</code> 校验和</td><td>写现场写到一半被狗咬——<code>cause</code> 已新、<code>check</code> 仍旧，和不齐则判无效</td></tr><tr><td><code>uptime_ms</code> 心跳</td><td>只知道&quot;死过&quot;没用，要知道&quot;死前跑到哪一步、卡了多久&quot;</td></tr></tbody></table><p>两个设计细节：</p><ul><li><p><strong>校验和用简单求和即可</strong>。目标不是防恶意篡改，是防&quot;写一半被复位&quot;的不一致状态；</p></li><li><p><strong>消费即失效</strong>。启动时读完现场、报告完毕，把 <code>magic</code> 写 0。否则同一次死亡会在后续每次启动被反复报告，刷屏且失去意义。</p></li></ul><h4 id="_1-3-位置信息-崩溃有精确坐标-卡死只有最后足迹" tabindex="-1">1.3 位置信息：崩溃有精确坐标，卡死只有最后足迹 <a class="header-anchor" href="#_1-3-位置信息-崩溃有精确坐标-卡死只有最后足迹" aria-label="Permalink to &quot;1.3 位置信息：崩溃有精确坐标，卡死只有最后足迹&quot;">​</a></h4><p>六个字段里，<code>pc_hint</code> 号称能指出死机位置，但它的注释写着&quot;HardFault 时有值&quot;——卡死时它没有值。原因在于一个容易误解的事实：</p><p><strong>看门狗复位本身不携带任何位置信息。</strong> IWDG 只是个倒计时器，超时就复位，它不知道程序死在哪；而复位一发生，内核寄存器（包括 PC）全部归零。也就是说，<strong>死机瞬间的程序位置，硬件上不会留下任何痕迹</strong>，想要它，只能靠程序死前自己写进 SRAM。</p><p>&quot;死前写&quot;这个机会，两种死法完全不同。</p><p><strong>崩溃（HardFault / 总线错误）——有精确坐标。</strong> 崩溃时异常 handler 还在执行，现场就压在栈上：栈帧里的 PC 就是出错指令地址，<code>SCB-&gt;CFSR</code> 说明错误类型，<code>MMFAR</code> / <code>BFAR</code> 给出非法访问的地址。handler 第一时间把这些写进 NOINIT，再等狗咬。本文 <code>pc_hint</code> 的值就来自这里；栈帧八件套（R0~R3 / R12 / LR / PC / xPSR）的全量采集与解读见 LV005，需要更细的出错原因时再补 <code>SCB-&gt;CFSR</code> 错误码。</p><p><strong>卡死（死循环 / 关中断死等）——只有最后足迹。</strong> 卡死意味着代码不再执行，死前不会有任何语句替你写现场。位置只能靠运行中<strong>持续刷新的记录</strong>反推，三个工具：</p><ul><li><p><strong>位置埋点</strong>：在关键路径的各节点放一条&quot;记录当前位置&quot;的语句，每经过一次就覆盖刷新（位置编号可用 <code>__LINE__</code> 宏自动生成）。重启后，最后写入的那个编号就是卡点附近——相当于软件版的 PC；</p></li><li><p><strong>双心跳</strong>：两个计数器分开更新，一个在 SysTick 中断里累加，一个在主循环里刷新。重启后对比：中断计数还在涨、主循环心跳停了 = 主循环死了但中断活着；两个都停 = 中断被关或时钟出了问题；</p></li><li><p><strong>心跳差值</strong>：主循环心跳的停更时刻与狗咬时刻之差就是卡死持续时长（2.3 小节），结合 IWDG 超时配置可反推卡点出现的早晚。</p></li></ul><p>如果一定要卡死瞬间的真实 PC，只有一条软件路：换 WWDG 并启用 EWI（早期唤醒中断）——它在复位前一拍触发中断，在 EWI 里抓取被打断处的 PC / LR 写入 NOINIT。但前提苛刻：卡死时全局中断没被关、时钟还在跑；且 IWDG 没有对应机制。硬件级的 PC 记录（ETM / Trace）需要调试器在线，离线的看门狗重启场景用不上。</p><p>一句话总结：<strong>崩溃是&quot;死时写&quot;，卡死是&quot;生前写&quot;</strong>——全景表里&quot;异常栈帧&quot;一类只在崩溃时可得，卡死场景依赖的是&quot;运行状态&quot;一类。</p><h3 id="_2-看门狗场景的完整闭环" tabindex="-1">2. 看门狗场景的完整闭环 <a class="header-anchor" href="#_2-看门狗场景的完整闭环" aria-label="Permalink to &quot;2. 看门狗场景的完整闭环&quot;">​</a></h3><h4 id="_2-1-时序" tabindex="-1">2.1 时序 <a class="header-anchor" href="#_2-1-时序" aria-label="Permalink to &quot;2.1 时序&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常运行     主循环每 500ms  noinit_tick(HAL_GetTick())  只刷新心跳与校验和</span></span>
<span class="line"><span>卡死         noinit_save(CAUSE_DEADLOOP, 0) 写死因 -&gt; 进死循环 -&gt; 心跳停更</span></span>
<span class="line"><span>3s 后        IWDG 复位 -&gt; SRAM 内容保持 -&gt; __main 不清 NOINIT 段</span></span>
<span class="line"><span>启动         noinit_init() 读到有效现场 -&gt; 串口报告死因 / 心跳 / 复位源 -&gt; 清 magic</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h4 id="_2-2-复位源判读-rcc-csr" tabindex="-1">2.2 复位源判读：<code>RCC-&gt;CSR</code> <a class="header-anchor" href="#_2-2-复位源判读-rcc-csr" aria-label="Permalink to &quot;2.2 复位源判读：\`RCC-&gt;CSR\`&quot;">​</a></h4><p><code>noinit_init()</code> 第一步读 <code>RCC-&gt;CSR</code> 存快照，用标志位回答&quot;是不是狗咬的&quot;：<code>IWDGRSTF</code>（独立看门狗）、<code>WWDGRSTF</code>（窗口看门狗）、<code>SFTRSTF</code>（软复位）、<code>PORRSTF</code> / <code>PINRSTF</code>（上电 / 引脚）、<code>LPWRRSTF</code>（低功耗管理）。判读标准与 <a href="/scm-docs/sdoc/basic/fault-and-hang/126d629b776b05818a2b701b.html">LV001</a> 第三章第 1 节的复位源判读一致。</p><p><strong>读完必须调 <code>__HAL_RCC_CLEAR_RESET_FLAGS()</code> 清除</strong>——这些标志位复位后不清零，会一直累积，不处理下次就分不清是哪次复位留下的。</p><h4 id="_2-3-心跳的语义" tabindex="-1">2.3 心跳的语义 <a class="header-anchor" href="#_2-3-心跳的语义" aria-label="Permalink to &quot;2.3 心跳的语义&quot;">​</a></h4><p><code>uptime_ms</code> 不是&quot;运行总时间&quot;，而是&quot;<strong>最后一次确认活着的时刻</strong>&quot;。卡死瞬间心跳自然停在最后有效值，配合本次启动时间，两者的差就是&quot;从卡死到被狗咬&quot;持续的时长——结合 IWDG 的超时配置（本文示例为 3s），可以反推出死循环发生的大致位置。</p><p>工程上的配套约束：<strong>喂狗点与心跳点放在同一处</strong>。心跳停了就等于喂狗停了，两个信号同源，事后分析不会互相矛盾。</p><h4 id="_2-4-死前显式保存" tabindex="-1">2.4 死前显式保存 <a class="header-anchor" href="#_2-4-死前显式保存" aria-label="Permalink to &quot;2.4 死前显式保存&quot;">​</a></h4><p><code>deadloop</code> 测试命令、HardFault handler 这类&quot;已知要死&quot;的路径，在进死循环前调 <code>noinit_save()</code> 写入 <code>cause</code> 与 <code>pc_hint</code>，死因就从&quot;推断&quot;变成&quot;自报&quot;。不写也能靠心跳 + 复位源兜底推断，写了原因更明确——LV005 的 HardFault 打印版同样适合在这里插一个保存点，打印与落盘二选一或兼得。</p><h2 id="四、边界与小结" tabindex="-1">四、边界与小结 <a class="header-anchor" href="#四、边界与小结" aria-label="Permalink to &quot;四、边界与小结&quot;">​</a></h2><h3 id="_1-边界与局限" tabindex="-1">1. 边界与局限 <a class="header-anchor" href="#_1-边界与局限" aria-label="Permalink to &quot;1. 边界与局限&quot;">​</a></h3><ul><li><p><strong>只对热复位有效</strong>。看门狗复位、软复位后 SRAM 保持，现场可读；拔电重插后 SRAM 随机，<code>magic</code> 不匹配自动丢弃——安全，但没有现场；</p></li><li><p><strong>不替代 Flash 落盘</strong>。掉电即丢是硬件特性，需要&quot;跨上电周期&quot;的场景仍然要写 Flash（LV001 的两条边界在这里依然成立）；</p></li><li><p><strong>半写风险靠 <code>check</code> 兜底</strong>，靠的是&quot;校验失败即无效&quot;的保守策略，而不是原子性——SRAM 写入没有原子保证；</p></li><li><p><strong><code>.ARM.__at_</code> 是 ARM 编译器专有语法</strong>，换 GCC 工具链要改用 ld 脚本 <code>NOLOAD</code>（LV001 的形态）。</p></li></ul><h3 id="_2-小结" tabindex="-1">2. 小结 <a class="header-anchor" href="#_2-小结" aria-label="Permalink to &quot;2. 小结&quot;">​</a></h3><p>三种形态各管一段：<strong>LV005 的串口打印</strong>胜在当场可读，适合调试期；<strong>LV001 的 Flash 落盘</strong>胜在跨上电周期，适合必须溯源的发布版；<strong>本文的 NOINIT 热复位保留</strong>胜在零外设依赖、零延迟，是看门狗自动重启场景的标配——狗咬之后重启的那一刻，现场已经躺在 SRAM 里等着被读出来了。</p><p>组合用法：调试期用打印版快速定位，定位后换 NOINIT 版发布；现场问题回归时，靠 NOINIT 心跳 + 复位标志判断&quot;是否狗咬、死前到哪一步&quot;，再按需补 Flash 落盘。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,93)])])}const k=a(n,[["render",d]]);export{u as __pageData,k as default};
